import{z as p,x as B,o as r,c as A,q as n,j as t,D as i,d as l,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Slope Trick","description":"","frontmatter":{"title":"Slope Trick","date":"2026-09-27T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/slope-trick.md","filePath":"cs/slope-trick.md","lastUpdated":1791063341000}'),d={name:"cs/slope-trick.md"};function m(c,a,x,D,_,f){const o=B("Mermaid");return r(),A("div",null,[a[2]||(a[2]=n('<h1 id="slope-trick" tabindex="-1">Slope Trick <a class="header-anchor" href="#slope-trick" aria-label="Permalink to &quot;Slope Trick&quot;">​</a></h1><div class="epigraph"><p>DP 的状态函数是分段凸的，就别存函数存斜率：两个堆各抱一头，加绝对值、整体平移都是常数级操作。</p><footer>—— 据 competitive programming 中 Slope Trick 技法；Aksenov (2015) 系统化</footer></div><p><a href="/cs/slope-trick">Slope Trick</a> 补的是 DP 优化的一个空档：转移里出现 \\(|x-a|\\)、\\(\\max(0,\\cdot)\\) 这类折线时，把整条分段凸函数塞进两个堆里维护，转移从「枚举状态」降为「堆顶增删」。上一课的计数在数方案，本课在算最优值——凸性是共同的靠山。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典母题：序列每步可 \\(\\pm 1\\) 或不动，代价为与目标序列差的绝对值之和，求最小代价；或「把数组变成非降序的最少改动」。朴素 DP 状态是「以 \\(i\\) 结尾、末值为 \\(x\\)」的函数 \\(f_i(x)\\)，\\(x\\) 连续则没法直接存。缺口：<strong>分段凸函数的增量维护</strong>。本课不碰严格凹或高次项——那要换成李超线段树或凸包。</p><p><span class="marginnote">术语翻译：breakpoint（拐点）= 斜率发生变化的 \\(x\\) 坐标；Slope Trick 把「拐点存进堆」当原子操作，函数本身从不显式写出。</span></p><p><span class="marginnote">数字实例：\\(f(x)=|x-3|+|x-5|\\) 在 \\([3,5]\\) 上斜率为 0、最小值 0。用堆表示：左堆存 \\(\\{3\\}\\)（斜率 \\(\\lt 0\\) 段的拐点）、右堆存 \\(\\{5\\}\\)，再加常数 \\(-0\\)。函数存在，数值却只有两个数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三条原子操作覆盖常见转移：加常数（改堆外一个 Lazy 值）；加 \\(|x-a|\\)（左堆 push \\(a\\)、右堆 push \\(a\\)，再弹堆调整答案）；取 \\(\\min\\) 后平移（把一侧堆整体清到顶、另一侧保留）。以「非降序列最小 L1 改动」为例：\\(f_i(x)=\\min_{y\\le x} f_{i-1}(y)+|x-a_i|\\)，先对 \\(f_{i-1}\\) 做前缀 min（右堆只留顶），再加 \\(|x-a_i|\\)。</p>',9)),(r(),t(E,null,{default:i(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22f_%7Bi-1%7D(x)%3A%20%E5%88%86%E6%AE%B5%E5%87%B8%22%5D%20--%3E%20B%5B%22%E5%89%8D%E7%BC%80%20min%3A%20%E5%8F%B3%E5%A0%86%E6%B8%85%E5%88%B0%E9%A1%B6%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%8A%A0%20%7Cx%20-%20a_i%7C%22%5D%0A%20%20C%20--%3E%20D%7B%22a_i%20%E4%B8%8E%E9%A1%B6%E9%83%A8%E6%AE%B5%3F%22%7D%0A%20%20D%20--%3E%7C%22%E8%90%BD%E5%9C%A8%E6%9C%80%E5%B0%8F%E5%B9%B3%E5%8F%B0%22%7C%20E%5B%22push%20a%20%E5%88%B0%E4%B8%A4%E5%A0%86%22%5D%0A%20%20D%20--%3E%7C%22%E5%81%8F%E5%B7%A6%2F%E5%81%8F%E5%8F%B3%22%7C%20F%5B%22%E5%BC%B9%E5%A0%86%E5%B9%B6%E7%B4%AF%E8%AE%A1%E5%B7%AE%E5%80%BC%22%5D%0A%20%20E%20--%3E%20G%5B%22f_i(x)%20%E5%B0%B1%E7%BB%AA%22%5D%0A%20%20F%20--%3E%20G%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：左堆是「下坡的坡顶档案」，右堆是「上坡的坡底档案」，中间永远是一段平地（最优区间的全体 \\(x\\)）。加 \\(|x-a|\\) 相当于在 \\(a\\) 处放一个 V 形卡子：卡子若落在平台内，\\(a\\) 同时成为左右档案的新条目；落在坡上，就把原来的条目挤出去一层。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"正确性系于一条守恒律：分段凸函数的斜率序列，左段斜率非增、右段非减，堆内元素按「每个拐点贡献一单位斜率」编码。前缀 min 只可能削平右侧，故右堆保留最小拐点即可；加 \\(|x-a|\\) 让斜率整体 \\(-1\\to+1\\) 跳变一次，恰好对应左右各进出堆常数次。每个操作都保持「堆深 = 函数复杂度」，所以总复杂度 \\(O(n\\log n)\\)。",-1)),(r(),t(E,null,{default:i(()=>[s(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BD%AC%E7%A7%BB%20%3D%20%E5%89%8D%E7%BC%80min%20%2B%20%E6%8A%98%E7%BA%BF%22%5D%20--%3E%7C%22%E5%8F%B3%E5%A0%86%E5%8F%AA%E7%95%99%E9%A1%B6%22%7C%20R%5B%22min%20%E4%BF%9D%E8%AF%81%22%5D%0A%20%20Q%20--%3E%7C%22V%20%E5%BD%A2%E5%8D%A1%E5%AD%90%22%7C%20L%5B%22%E6%96%9C%E7%8E%87%20%C2%B11%20%E8%B7%B3%E5%8F%98%22%5D%0A%20%20R%20--%3E%20S%5B%22%E5%A0%86%E6%93%8D%E4%BD%9C%E5%AE%88%E6%81%92%22%5D%0A%20%20L%20--%3E%20S%0A%20%20S%20--%3E%20T%5B%22O(n%20log%20n)%20%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：数组 3 5 2 7 变非降。\\(f_1=|x-3|\\)，平台 \\(\\{3\\}\\)，min \\(0\\)；加 \\(|x-5|\\)（5 不在平台左侧）答案 \\(+0\\)，\\(f_2\\) 平台 \\(\\{5\\}\\)；加 \\(|x-2|\\)（2 在平台左侧）弹右堆顶 5，答案 \\(+5-2=3\\)，平台移到 \\([3,5]\\)；加 \\(|x-7|\\)（7 在右侧）\\(+0\\)。总代价 \\(3\\)，最优终点取 \\(x=7\\)，目标序列如 3 5 5 7（把 2 改成 5）。</span></p><p><span class="marginnote">常见误区：把 Slope Trick 当成「堆优化」的万金油——它要求被维护的函数<strong>分段线性且凸</strong>；二次代价 \\(\\lambda(x-a)^2\\) 会让斜率连续变化，堆表示直接失效，此时应换凸包或三分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>适用信号：转移含绝对值、\\(\\max/\\min\\)、且能证明状态函数凸。不适用：凹代价、多维状态（多维凸即 L♮ 凸，堆表示不够）、需要还原具体方案（要额外存被弹拐点，空间乘 \\(n\\)）。与其他优化关系：SMAWK 处理「行最小值位置单调」但函数不必凸；李超树查任意一次函数最值但不做增量合并——Slope Trick 卡在「凸 + 可堆」这个交叉点上。</p><p><span class="marginnote">直觉类比：这像水管工不用整张图纸，只记录两摞弯头清单；每接一根新管（新元素），要么把弯头插进清单，要么顶掉一个旧弯头并记一笔工钱（答案增量）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分段凸 DP 函数 = 左右两个堆 + 一个常数，加 \\(|x-a|\\) 与前缀 min 都是均摊 \\(O(\\log n)\\)。</li><li>守恒律是「拐点 = 一单位斜率」，堆深即函数复杂度。</li><li>二次项、凹函数、多维状态都出圈，各有对应工具。</li><li>出处：Aksenov「Slope Trick」方法笔记 (2015)；CF 题解 conventional 口径；SMAWK: Aggarwal et al. 1987。</li></ul>',7))])}const h=p(d,[["render",m]]);export{C as __pageData,h as default};
